"""Private evidence storage interface (D-P0-007 s5; decision C-6).

* Object keys are generated by the SERVER from UUIDs only (`tenants/<tenant>/evidence/<revision>`); a key supplied by anyone else, or one that
  would leave the store root, is refused. The original file name is metadata and never part of a key or path.
* `LocalDevStore` writes to a local directory: **DEV-ONLY**. It is not a private object store (no server-side encryption, no separate account,
  no versioning); `config.settings.prod` refuses to start with it. The production store depends on the hosting decision (open item O-4).
"""
from __future__ import annotations

import hashlib
import os
import re
import uuid
from collections.abc import Iterable, Iterator
from pathlib import Path
from typing import BinaryIO

from django.conf import settings

_U = r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"
KEY_RE = re.compile(rf"^tenants/{_U}/evidence/{_U}$")
CHUNK = 1 << 20


class StoreError(Exception):
    pass


class TooLarge(StoreError):
    pass


def object_key(tenant_id, revision_id) -> str:
    return f"tenants/{uuid.UUID(str(tenant_id))}/evidence/{uuid.UUID(str(revision_id))}"


class LocalDevStore:
    dev_only = True

    def __init__(self, root: str):
        if not root:
            raise StoreError("EVIDENCE_STORE_DIR is not configured")
        self.root = Path(root).resolve()

    def _path(self, key: str) -> Path:
        if not KEY_RE.fullmatch(key or ""):
            raise StoreError("invalid object key")
        p = (self.root / key).resolve()
        if not p.is_relative_to(self.root):  # defence in depth: the pattern already excludes separators and dots
            raise StoreError("object key escapes the store")
        return p

    def put(self, key: str, chunks: Iterable[bytes], *, max_bytes: int) -> tuple[int, str]:
        """Write exclusively (never overwrites an existing object); returns (size, sha256 hex). Partial objects are removed on failure."""
        p = self._path(key)
        p.parent.mkdir(parents=True, exist_ok=True)
        h, size = hashlib.sha256(), 0
        fd = os.open(p, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        try:
            with os.fdopen(fd, "wb") as fh:
                for c in chunks:
                    size += len(c)
                    if size > max_bytes:
                        raise TooLarge("object exceeds the size limit")
                    h.update(c)
                    fh.write(c)
        except BaseException:
            p.unlink(missing_ok=True)
            raise
        return size, h.hexdigest()

    def open(self, key: str) -> BinaryIO:
        try:
            return open(self._path(key), "rb")  # noqa: SIM115 - the caller owns and closes the handle
        except FileNotFoundError as exc:
            raise StoreError("object not found") from exc

    def iter_chunks(self, key: str) -> Iterator[bytes]:
        with self.open(key) as fh:
            while chunk := fh.read(CHUNK):
                yield chunk

    def delete(self, key: str) -> None:
        self._path(key).unlink(missing_ok=True)


def get_store() -> LocalDevStore:
    if getattr(settings, "EVIDENCE_STORE_BACKEND", "") == "local_dev":
        return LocalDevStore(settings.EVIDENCE_STORE_DIR)
    raise StoreError("no private object store is configured (open item O-4); only the DEV-ONLY local store exists")
